-- ============================================================
-- SEED EXT 3: Módulo 23 — Advanced Modals (ex 106-205)
-- Novos tópicos: dare/need marginais, can't help, would
-- (willingness/refusal), modais em reported speech, TOEFL C1
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'advanced-modals';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo advanced-modals não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 31: dare e need como modais marginais
  (cid,31,106,'multiple_choice','What is the difference between "He dare not speak" and "He doesn''t dare to speak"?','Both are correct; the first uses dare as a modal (no auxiliary, no to); the second uses dare as a main verb (with do + to).','["Only the first is correct","Both are correct; the first uses dare as a modal (no auxiliary, no to); the second uses dare as a main verb (with do + to).","Only the second is correct","Dare cannot be used in negative sentences"]','Dare = marginal modal (dare + base verb) OR main verb (dare to + inf). Both valid.','hard'),
  (cid,31,107,'gap_fill','How dare she _____ (challenge) the committee''s authority in such a public forum!','challenge',NULL,'"How dare + subject + base verb" = dare as modal in indignant exclamation.','hard'),
  (cid,31,108,'multiple_choice','Which sentence uses "need" as a modal (not a main verb)?','Need she attend the entire conference?','["She needs to attend the entire conference.","She doesn''t need to attend the entire conference.","Need she attend the entire conference?","She is needed to attend the entire conference."]','"Need + subject + base verb?" = modal "need" in formal question (British English).','hard'),
  (cid,31,109,'gap_fill','You _____ (need + not) submit the form again — we have all the information we require.','needn''t',NULL,'"Needn''t + base verb" = modal "need" in negative. More concise than "don''t need to."','medium'),
  (cid,31,110,'multiple_choice','What is the difference between "You needn''t have done that" and "You didn''t need to do that"?','"Needn''t have done" = you did it, but it was unnecessary. "Didn''t need to do" = it wasn''t necessary (and you probably didn''t do it).','["They are identical","''Needn''t have done'' = you didn''t do it; ''didn''t need to'' = you did","''Needn''t have done'' = you did it, but it was unnecessary. ''Didn''t need to do'' = it wasn''t necessary (and you probably didn''t do it).","Both imply the action was not done"]','"Needn''t have done" = retrospective unnecessary action (you wasted the effort).','hard'),
  (cid,31,111,'gap_fill','She _____ (need + not/have/apologize) — her paper was rejected for methodological reasons, not personal ones.','needn''t have apologized',NULL,'"Needn''t have + past participle" = the apology was done but unnecessary.','hard'),
  (cid,31,112,'multiple_choice','Which sentence uses dare or need as a modal INCORRECTLY?','She dares not to speak in the presence of senior colleagues.','["Dare I say it, the findings are revolutionary.","She dared not challenge the established theory (modal dare in past).","Need we submit the application before the deadline?","She dares not to speak in the presence of senior colleagues."]','"Dares not to speak" — modal dare never takes "to." Should be: "dare not speak."','hard'),

  -- BLOCK 32: can't help + gerund
  (cid,32,113,'gap_fill','She _____ (can''t help / notice) the inconsistencies in the data, even when she tries to focus on the broader pattern.','can''t help noticing',NULL,'"Can''t help + gerund" = unable to prevent oneself from doing something.','medium'),
  (cid,32,114,'multiple_choice','Which sentence uses "can''t help" correctly?','The researcher couldn''t help being impressed by the elegance of the solution.','["The researcher couldn''t help to be impressed by the solution.","The researcher couldn''t help be impressed by the solution.","The researcher couldn''t help being impressed by the elegance of the solution.","The researcher can''t help was impressed by the solution."]','"Can''t/couldn''t help + gerund (being)." Not infinitive.','medium'),
  (cid,32,115,'gap_fill','I _____ (can''t help/wonder) whether the anomaly in Block 3 was caused by measurement error.','can''t help wondering',NULL,'"Can''t help wondering" = the thought arises spontaneously.','easy'),
  (cid,32,116,'multiple_choice','The phrase "I couldn''t help but notice" is:','An older idiomatic variant of "I couldn''t help noticing" — both are correct.','["Grammatically incorrect","More formal than ''I couldn''t help noticing''","An older idiomatic variant of ''I couldn''t help noticing'' — both are correct.","Only used in British English"]','"Can''t help but + base verb" = fixed idiom, equivalent to "can''t help + gerund."','hard'),

  -- BLOCK 33: would for willingness and refusal
  (cid,33,117,'multiple_choice','In "The engine wouldn''t start despite several attempts," "wouldn''t" expresses:','Refusal or failure (the engine behaved as if it refused to start).','["Past habitual action","Conditional","Refusal or failure (the engine behaved as if it refused to start).","Future in the past"]','"Wouldn''t" for inanimate subjects = persistent failure/refusal.','hard'),
  (cid,33,118,'gap_fill','No matter how many times they called, he _____ (would not/answer) the phone.','wouldn''t answer',NULL,'"Wouldn''t + base verb" = refusal (deliberate/persistent).','medium'),
  (cid,33,119,'multiple_choice','Which sentence uses "would" for willingness?','She would always help her colleagues with their statistics, no matter how busy she was.','["She would help if she had time (conditional).","She would have helped if asked (Type 3 conditional).","She would always help her colleagues with their statistics, no matter how busy she was.","She would help tomorrow if necessary."]','"Would always + base verb" for habitual willingness (positive characteristic).','medium'),
  (cid,33,120,'gap_fill','The machine _____ (would/work) properly — it kept shutting down after five minutes of operation.','wouldn''t',NULL,'"Wouldn''t work" = refusal/malfunction (inanimate subject).','easy'),
  (cid,33,121,'multiple_choice','The sentence "She would spend hours in the library, reading everything she could find on the topic" uses "would" for:','Past habit (characteristic repeated action).','["Future in the past","Refusal","Past habit (characteristic repeated action).","Conditional"]','"Would + base verb" for vivid narrative of past habits (characteristic behavior).','medium'),

  -- BLOCK 34: modais em reported speech
  (cid,34,122,'gap_fill','Direct: "You must submit the application before Friday." → Reported: She said we _____ (must) submit the application before Friday / by the following Friday.','had to / must',NULL,'"Must" → "had to" (backshift) OR "must" (if the obligation is still valid). Both possible.','hard'),
  (cid,34,123,'multiple_choice','Which modals do NOT change in reported speech?','Could, would, might, should, ought to.','["Can, may, will, shall","Could, would, might, should, ought to.","Must, need, dare","All modals change in reported speech"]','Past modals (could/would/might/should/ought to) are already "past" — no backshift needed.','hard'),
  (cid,34,124,'gap_fill','Direct: "You may leave early today." → Reported: The manager said we _____ leave early that day.','could / might',NULL,'"May" (permission) → "could" or "might" in reported speech.','hard'),
  (cid,34,125,'multiple_choice','Direct: "You should reconsider your methodology." → Best reported speech version?','She advised us that we should reconsider our methodology.','["She advised us that we ought reconsider our methodology.","She advised us that we should reconsider our methodology.","She advised us that we should have reconsidered our methodology (implies we didn''t).","She advised us that we would reconsider our methodology."]','"Should" stays "should" in reported speech (no backshift — already a past form).','medium'),
  (cid,34,126,'gap_fill','Direct: "Will you help me with the analysis?" → Reported: He asked whether she _____ help him with the analysis.','would',NULL,'"Will" → "would" in reported speech (backshift of will).','easy'),
  (cid,34,127,'multiple_choice','Direct: "I might attend the conference." → Reported form?','She said she might attend the conference.','["She said she may attend the conference.","She said she might attend the conference.","She said she will attend the conference.","She said she could attend the conference."]','"Might" does not backshift — already past form. Stays "might."','easy'),

  -- BLOCK 35: perfect modals for missed opportunities
  (cid,35,128,'gap_fill','She _____ (could/have/become) a world-class researcher, but she chose to leave academia.','could have become',NULL,'"Could have + past participle" = unrealized past potential.','medium'),
  (cid,35,129,'multiple_choice','What does "He might have succeeded had the funding not been withdrawn" mean?','Success was possible but was prevented by the funding loss.','["He definitely succeeded","He definitely failed","Success was possible but was prevented by the funding loss.","He succeeded despite the funding loss"]','"Might have + past participle" = possible (not certain) unrealized outcome.','medium'),
  (cid,35,130,'gap_fill','They _____ (should/have/consult) the ethics board before beginning the clinical trial.','should have consulted',NULL,'"Should have + past participle" = criticism of past omission.','easy'),
  (cid,35,131,'multiple_choice','Which sentence expresses the STRONGEST regret about a past decision?','I should never have agreed to co-author a paper I wasn''t involved in writing.','["I might not have agreed to co-author the paper.","I could not have agreed to co-author the paper.","I should never have agreed to co-author a paper I wasn''t involved in writing.","I would not have agreed to co-author the paper (conditional — different nuance)."]','"Should never have + past participle" = strong retrospective regret/criticism.','medium'),
  (cid,35,132,'gap_fill','The discovery _____ (might/have/make) a significant impact on the field, but the paper was never published.','might have made',NULL,'"Might have + past participle" = speculative past possibility.','medium'),

  -- BLOCK 36: TOEFL Reading
  (cid,36,133,'multiple_choice','[TOEFL Reading] "The bridge wouldn''t withstand the increased load, so the project was abandoned." "Wouldn''t" here expresses:','Inability/persistent failure (the bridge was incapable of bearing the load).','["Future prediction","Past habit","Inability/persistent failure (the bridge was incapable of bearing the load).","Conditional outcome"]','"Wouldn''t" for persistent inability/failure (inanimate subject).','medium'),
  (cid,36,134,'gap_fill','[TOEFL Reading] "Darwin _____ (dare + not) publish his findings for twenty years, fearing the reaction of the religious establishment." Best form?','dared not',NULL,'"Dared not + base verb" = modal dare in past negative.','hard'),
  (cid,36,135,'multiple_choice','[TOEFL Reading] "The government of the time could have introduced universal healthcare but chose not to." This means:','The capacity existed but the political will did not.','["The government introduced universal healthcare","Universal healthcare was impossible","The capacity existed but the political will did not.","Universal healthcare was unnecessary"]','"Could have + past participle" = unrealized past ability.','medium'),
  (cid,36,136,'gap_fill','[TOEFL Reading] "Scientists studying early Mars needn''t _____ (restrict) their investigations to the most recent geological period." Best form?','restrict',NULL,'"Needn''t + base verb" = not necessary. Modal "need" in negative.','hard'),
  (cid,36,137,'multiple_choice','[TOEFL Reading] "She reported that the preliminary results might suggest a causal link." "Might" is used in reported speech because:','It is the reported form of "may" (backshift) or was already "might" in the original statement.','["Might is more polite than may","Might is the future tense","It is the reported form of ''may'' (backshift) or was already ''might'' in the original statement.","Might is required in all academic reports"]','"May" → "might" in reported speech (backshift), or "might" stays "might."','hard'),

  -- BLOCK 37: TOEFL Speaking
  (cid,37,138,'production','[TOEFL Speaking — 45s] A reading discusses how early scientists dared to challenge established theories. Summarize and respond. Use: dared not, couldn''t help, could have, should have, would (habit), needn''t have.','',NULL,'Galileo dared not publicly promote his heliocentric theory under threat of inquisition, yet he couldn''t help continuing his observations in private. He could have been more cautious in his final publications, and his defenders argued he needn''t have provoked the Church so directly. Yet history shows he should have been celebrated rather than persecuted. Generations of scientists would gather evidence quietly, awaiting a more tolerant intellectual climate before publishing findings that contradicted official doctrine.','hard'),
  (cid,37,139,'production','[TOEFL Speaking — 45s] A professor says that technology companies should have been regulated earlier. Agree or disagree. Use: should have been, could have been, might have been, wouldn''t, need not have.','',NULL,'I strongly agree. Governments should have been more proactive in regulating social media platforms in the early 2010s, before their influence became deeply entrenched. Many of the harms we now associate with social media — algorithmic radicalization, erosion of privacy, political manipulation — might have been prevented had appropriate oversight frameworks been established earlier. Regulators apparently wouldn''t listen to academic warnings about data misuse, and platforms certainly needn''t have been given a decade of essentially self-regulated operation. The social costs of this delay have been enormous.','hard'),

  -- BLOCK 38: TOEFL Writing
  (cid,38,140,'production','[TOEFL Writing — 150 words] Write an academic paragraph analyzing a historical policy failure using at least 5 different modal structures: could have, should have, might have, wouldn''t, needn''t have, dared not.','',NULL,'The global response to the 2008 financial crisis illustrates how regulatory failures can have catastrophic consequences. Regulators dared not challenge the dominant economic consensus that financial markets were inherently self-correcting. Governments should have imposed stricter capital requirements on banks years before the crisis emerged. Risk assessment models might have performed better had they incorporated data from historical financial panics rather than relying solely on recent performance. Financial institutions wouldn''t accept regulatory oversight, lobbying aggressively against reforms that might have constrained their profitability. In retrospect, policymakers needn''t have been so deferential to the banking lobby — the public interest should always have taken precedence. The lesson is clear: could have and should have are insufficient responses to structural failures; what is needed is political courage to act in advance of a catastrophe.','hard'),
  (cid,38,141,'production','[TOEFL Writing — Error Correction] Fix modal errors: "She dares not to speak at the meeting. He couldn''t help to notice the error. She would to study late every evening. They said they may attend the conference. You needn''t have to worry — it''s already done."','',NULL,'dares not to speak → dare not speak (modal dare: no to, no -s); couldn''t help to notice → couldn''t help noticing (can''t help + gerund); would to study → would study (would + bare base verb, no to); may → might (backshift of may in reported speech); needn''t have to worry → needn''t have worried (needn''t have + past participle) OR needn''t worry (present).','hard'),
  (cid,38,142,'production','[TOEFL Writing — 200 words] Write a TOEFL-style essay paragraph about "The responsibility of universities in preparing students for a changing job market." Use: should have, could have, might have, ought to, would rather, can''t help, need not, dare to.','',NULL,'Universities ought to prepare graduates not merely for the jobs that exist today but for roles that do not yet exist. Critics argue that higher education institutions should have adapted their curricula far more rapidly in response to the digital economy — the lag between industry needs and academic offerings might have been avoided had universities maintained stronger partnerships with employers. One can''t help noticing that graduates with critical thinking and adaptability skills tend to fare better in turbulent job markets than those with narrowly technical training. Students who dare to take interdisciplinary courses and embrace uncertainty are often better equipped for career transitions. Universities need not abandon traditional academic values to remain relevant; rather, they could have integrated emerging competencies into existing frameworks without sacrificing intellectual rigor. Many educators would rather focus exclusively on foundational knowledge, which is understandable. Be that as it may, the pace of technological change now requires a more dynamic and responsive approach to curriculum design.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
